{
  "format": "complete-a-commitment/1",
  "module": {
    "id": "growth-commitment",
    "version": "1.0.0",
    "template": {
      "id": "complete-a-commitment",
      "version": 1
    },
    "title": "Compare growth arrangements",
    "question": "Which growth commitments can we fund and deliver under the declared demand and collection situations?",
    "description": "Compare a current-approach baseline and three complete growth arrangements against cash by date, a required reserve, delivery capacity and a commitment cutoff. Forecast customer counts are uncertain situations, not controllable sales or probabilities. A passing arrangement is operationally supportable under these inputs; no most-profitable option is selected.",
    "units": {
      "time": "day",
      "timeOrigin": "elapsed whole days from the declared growth-planning origin",
      "money": "USD cent",
      "count": "customer",
      "hours": "hour"
    },
    "assumptions": [
      "This is an incremental growth calculation for one standard service package. Opening cash is already unrestricted growth funding after existing obligations; do not deduct those obligations again. The minimum reserve is an additional balance that must remain available.",
      "Each arrangement has a fixed committed campaign expense that remains payable when sales disappoint. Forecast customer counts determine delivery expense, receipts and workload. Costs are not automatically inferred from customer-acquisition ratios.",
      "Every declared situation supplies a complete joint forecast for all alternatives. Passing requires meeting every retained requirement in every declared situation; no probability of success or guarantee of customer demand is inferred.",
      "Cash uses explicit elapsed days and ordered atomic events. On the same day, campaign payment occurs first, delivery payment second, and customer receipt third. A later receipt cannot fund an earlier payment. Customer receipts are not treated as negative expenses or returned deposits.",
      "The payment-before-delivery alternative receives its complete customer price no later than delivery starts. Invoice alternatives collect no earlier than delivery finishes. The model assumes full receipt on each declared collection date; bad debt, refunds, tax and recognition rules require an authored extension.",
      "Capacity is available incremental hours in the explicitly identified delivery period. All customer work fits inside that period. The model does not spread work across periods, infer staffing from elapsed time, or solve a detailed task schedule.",
      "The comparison horizon must contain every payment, receipt and delivery completion. A multi-period contract needs its complete obligations inside this model or a new authored profile; its first month cannot stand for the whole commitment.",
      "The baseline represents no incremental campaign and no incremental customers. Its zero cash events are harmless placeholders. Feasibility-only comparison neither recommends a growth target nor estimates campaign effectiveness or causal impact."
    ],
    "inputs": {
      "parameters": {
        "openingCashMinor": {
          "type": "integer",
          "unit": "money",
          "minimum": 0
        },
        "minimumReserveMinor": {
          "type": "integer",
          "unit": "money",
          "minimum": 0
        },
        "unitPriceMinor": {
          "type": "integer",
          "unit": "money",
          "minimum": 0
        },
        "deliveryExpensePerCustomerMinor": {
          "type": "integer",
          "unit": "money",
          "minimum": 0
        },
        "deliveryHoursPerCustomer": {
          "type": "integer",
          "unit": "hours",
          "minimum": 1
        },
        "currentDay": {
          "type": "integer",
          "unit": "time",
          "minimum": 0
        },
        "decisionDeadlineDay": {
          "type": "integer",
          "unit": "time",
          "minimum": 0
        },
        "horizonDay": {
          "type": "integer",
          "unit": "time",
          "minimum": 1
        },
        "campaignSurplusTargetMinor": {
          "type": "integer",
          "unit": "money",
          "minimum": 0
        }
      },
      "tables": {
        "arrangements": {
          "key": [
            "id"
          ],
          "columns": {
            "id": {
              "type": "string",
              "enum": [
                "baseline",
                "large-invoice",
                "small-invoice",
                "medium-prepay"
              ]
            },
            "campaignExpenseMinor": {
              "type": "integer",
              "unit": "money",
              "minimum": 0
            }
          }
        },
        "scenarios": {
          "key": [
            "id"
          ],
          "columns": {
            "id": {
              "type": "string"
            },
            "label": {
              "type": "string"
            }
          }
        },
        "outcomes": {
          "key": [
            "scenario",
            "arrangement"
          ],
          "columns": {
            "scenario": {
              "type": "string",
              "references": {
                "table": "scenarios",
                "column": "id"
              }
            },
            "arrangement": {
              "type": "string",
              "enum": [
                "baseline",
                "large-invoice",
                "small-invoice",
                "medium-prepay"
              ]
            },
            "customers": {
              "type": "integer",
              "unit": "count",
              "minimum": 0
            },
            "campaignExpenseDay": {
              "type": "integer",
              "unit": "time",
              "minimum": 0
            },
            "deliveryExpenseDay": {
              "type": "integer",
              "unit": "time",
              "minimum": 0
            },
            "customerReceiptDay": {
              "type": "integer",
              "unit": "time",
              "minimum": 0
            },
            "deliveryStartDay": {
              "type": "integer",
              "unit": "time",
              "minimum": 0
            },
            "deliveryFinishDay": {
              "type": "integer",
              "unit": "time",
              "minimum": 0
            },
            "capacityPeriod": {
              "type": "string",
              "references": {
                "table": "capacityPeriods",
                "column": "id"
              }
            }
          }
        },
        "capacityPeriods": {
          "key": [
            "id"
          ],
          "columns": {
            "id": {
              "type": "string"
            },
            "from": {
              "type": "integer",
              "unit": "time",
              "minimum": 0
            },
            "through": {
              "type": "integer",
              "unit": "time",
              "minimum": 0
            },
            "availableHours": {
              "type": "integer",
              "unit": "hours",
              "minimum": 0
            }
          }
        },
        "_resources": {
          "key": [
            "id"
          ],
          "columns": {
            "id": {
              "type": "string"
            },
            "capacity": {
              "type": "integer",
              "unit": "count",
              "minimum": 0
            }
          }
        },
        "_bookings": {
          "key": [
            "id"
          ],
          "columns": {
            "id": {
              "type": "string"
            },
            "resource": {
              "type": "string"
            },
            "from": {
              "type": "integer",
              "unit": "time",
              "minimum": 0
            },
            "through": {
              "type": "integer",
              "unit": "time",
              "minimum": 0
            },
            "amount": {
              "type": "integer",
              "unit": "count",
              "minimum": 0
            }
          }
        }
      }
    },
    "choices": [
      {
        "id": "arrangement",
        "domain": {
          "values": [
            "baseline",
            "large-invoice",
            "small-invoice",
            "medium-prepay"
          ]
        }
      }
    ],
    "scenarioDomain": {
      "table": "scenarios"
    },
    "lookupCoverage": [
      {
        "table": "arrangements",
        "keys": {
          "id": {
            "domain": {
              "values": [
                "baseline",
                "large-invoice",
                "small-invoice",
                "medium-prepay"
              ]
            }
          }
        }
      },
      {
        "table": "outcomes",
        "keys": {
          "scenario": {
            "domain": {
              "table": "scenarios",
              "column": "id"
            }
          },
          "arrangement": {
            "domain": {
              "values": [
                "baseline",
                "large-invoice",
                "small-invoice",
                "medium-prepay"
              ]
            }
          }
        }
      }
    ],
    "derived": [
      {
        "id": "customers",
        "type": "integer",
        "unit": "count",
        "expr": {
          "op": "lookup",
          "table": "outcomes",
          "where": {
            "scenario": {
              "ref": "scenario.id"
            },
            "arrangement": {
              "ref": "choice.arrangement"
            }
          },
          "column": "customers"
        }
      },
      {
        "id": "campaignExpense",
        "type": "integer",
        "unit": "money",
        "expr": {
          "op": "lookup",
          "table": "arrangements",
          "where": {
            "id": {
              "ref": "choice.arrangement"
            }
          },
          "column": "campaignExpenseMinor"
        }
      },
      {
        "id": "customerReceipts",
        "type": "integer",
        "unit": "money",
        "expr": {
          "op": "mul",
          "args": [
            {
              "ref": "derived.customers"
            },
            {
              "ref": "parameter.unitPriceMinor"
            }
          ]
        }
      },
      {
        "id": "deliveryExpense",
        "type": "integer",
        "unit": "money",
        "expr": {
          "op": "mul",
          "args": [
            {
              "ref": "derived.customers"
            },
            {
              "ref": "parameter.deliveryExpensePerCustomerMinor"
            }
          ]
        }
      },
      {
        "id": "totalExpense",
        "type": "integer",
        "unit": "money",
        "expr": {
          "op": "add",
          "args": [
            {
              "ref": "derived.campaignExpense"
            },
            {
              "ref": "derived.deliveryExpense"
            }
          ]
        }
      },
      {
        "id": "contributionBeforeCampaign",
        "type": "integer",
        "unit": "money",
        "expr": {
          "op": "sub",
          "args": [
            {
              "ref": "derived.customerReceipts"
            },
            {
              "ref": "derived.deliveryExpense"
            }
          ]
        }
      },
      {
        "id": "netContribution",
        "type": "integer",
        "unit": "money",
        "expr": {
          "op": "sub",
          "args": [
            {
              "ref": "derived.contributionBeforeCampaign"
            },
            {
              "ref": "derived.campaignExpense"
            }
          ]
        }
      },
      {
        "id": "contributionPerCustomer",
        "type": "integer",
        "unit": "money",
        "expr": {
          "op": "sub",
          "args": [
            {
              "ref": "parameter.unitPriceMinor"
            },
            {
              "ref": "parameter.deliveryExpensePerCustomerMinor"
            }
          ]
        }
      },
      {
        "id": "campaignRecoveryTarget",
        "type": "integer",
        "unit": "money",
        "expr": {
          "op": "add",
          "args": [
            {
              "ref": "derived.campaignExpense"
            },
            {
              "ref": "parameter.campaignSurplusTargetMinor"
            }
          ]
        }
      },
      {
        "id": "capacityHours",
        "type": "integer",
        "unit": "hours",
        "expr": {
          "op": "mul",
          "args": [
            {
              "ref": "derived.customers"
            },
            {
              "ref": "parameter.deliveryHoursPerCustomer"
            }
          ]
        }
      },
      {
        "id": "availableHours",
        "type": "integer",
        "unit": "hours",
        "expr": {
          "op": "lookup",
          "table": "capacityPeriods",
          "where": {
            "id": {
              "op": "lookup",
              "table": "outcomes",
              "where": {
                "scenario": {
                  "ref": "scenario.id"
                },
                "arrangement": {
                  "ref": "choice.arrangement"
                }
              },
              "column": "capacityPeriod"
            }
          },
          "column": "availableHours"
        }
      },
      {
        "id": "capacityHeadroom",
        "type": "integer",
        "unit": "hours",
        "expr": {
          "op": "sub",
          "args": [
            {
              "ref": "derived.availableHours"
            },
            {
              "ref": "derived.capacityHours"
            }
          ]
        }
      },
      {
        "id": "campaignExpenseDay",
        "type": "integer",
        "unit": "time",
        "expr": {
          "op": "lookup",
          "table": "outcomes",
          "where": {
            "scenario": {
              "ref": "scenario.id"
            },
            "arrangement": {
              "ref": "choice.arrangement"
            }
          },
          "column": "campaignExpenseDay"
        }
      },
      {
        "id": "deliveryExpenseDay",
        "type": "integer",
        "unit": "time",
        "expr": {
          "op": "lookup",
          "table": "outcomes",
          "where": {
            "scenario": {
              "ref": "scenario.id"
            },
            "arrangement": {
              "ref": "choice.arrangement"
            }
          },
          "column": "deliveryExpenseDay"
        }
      },
      {
        "id": "customerReceiptDay",
        "type": "integer",
        "unit": "time",
        "expr": {
          "op": "lookup",
          "table": "outcomes",
          "where": {
            "scenario": {
              "ref": "scenario.id"
            },
            "arrangement": {
              "ref": "choice.arrangement"
            }
          },
          "column": "customerReceiptDay"
        }
      },
      {
        "id": "deliveryStartDay",
        "type": "integer",
        "unit": "time",
        "expr": {
          "op": "lookup",
          "table": "outcomes",
          "where": {
            "scenario": {
              "ref": "scenario.id"
            },
            "arrangement": {
              "ref": "choice.arrangement"
            }
          },
          "column": "deliveryStartDay"
        }
      },
      {
        "id": "deliveryFinishDay",
        "type": "integer",
        "unit": "time",
        "expr": {
          "op": "lookup",
          "table": "outcomes",
          "where": {
            "scenario": {
              "ref": "scenario.id"
            },
            "arrangement": {
              "ref": "choice.arrangement"
            }
          },
          "column": "deliveryFinishDay"
        }
      },
      {
        "id": "cashHeadroom",
        "type": "integer",
        "unit": "money",
        "expr": {
          "ref": "finance.minimumHeadroom"
        }
      },
      {
        "id": "peakFundingRequired",
        "type": "integer",
        "unit": "money",
        "expr": {
          "ref": "finance.peakFundingRequired"
        }
      },
      {
        "id": "minimumCashBalance",
        "type": "integer",
        "unit": "money",
        "expr": {
          "ref": "finance.lowestBalance"
        }
      },
      {
        "id": "endingCashBalance",
        "type": "integer",
        "unit": "money",
        "expr": {
          "ref": "finance.endingBalance"
        }
      }
    ],
    "activities": [],
    "resources": {
      "definitions": {
        "table": "_resources",
        "idColumn": "id",
        "capacityColumn": "capacity"
      },
      "bookings": {
        "table": "_bookings",
        "resourceColumn": "resource",
        "startColumn": "from",
        "endColumn": "through",
        "amountColumn": "amount"
      }
    },
    "requirements": [
      {
        "id": "CASH",
        "label": "Cash and reserve by date",
        "meaning": "Every ordered payment and receipt leaves at least the declared reserve.",
        "waivable": false
      },
      {
        "id": "CAPACITY",
        "label": "Delivery-period capacity",
        "meaning": "The complete forecast workload fits the available hours and interval of its declared delivery period.",
        "waivable": false
      },
      {
        "id": "TIME",
        "label": "Commitment cutoff and full horizon",
        "meaning": "New campaign choices remain available at the planning day and all future obligations fit the comparison horizon.",
        "waivable": false
      },
      {
        "id": "TERMS",
        "label": "Declared customer payment terms",
        "meaning": "Receipt dates preserve the published invoice or payment-before-delivery meaning.",
        "waivable": false
      },
      {
        "id": "BASIS",
        "label": "Incremental baseline meaning",
        "meaning": "Keeping the current approach adds no campaign expense and no forecast growth customers.",
        "waivable": false
      }
    ],
    "constraints": [
      {
        "id": "baseline-expense",
        "requirement": "BASIS",
        "kind": "predicate",
        "predicate": {
          "op": "eq",
          "args": [
            {
              "op": "lookup",
              "table": "arrangements",
              "where": {
                "id": {
                  "literal": "baseline"
                }
              },
              "column": "campaignExpenseMinor"
            },
            {
              "literal": 0
            }
          ]
        }
      },
      {
        "id": "baseline-customers",
        "requirement": "BASIS",
        "kind": "predicate",
        "predicate": {
          "op": "or",
          "args": [
            {
              "op": "not",
              "args": [
                {
                  "op": "eq",
                  "args": [
                    {
                      "ref": "choice.arrangement"
                    },
                    {
                      "literal": "baseline"
                    }
                  ]
                }
              ]
            },
            {
              "op": "eq",
              "args": [
                {
                  "ref": "derived.customers"
                },
                {
                  "literal": 0
                }
              ]
            }
          ]
        }
      },
      {
        "id": "cash-reserve",
        "requirement": "CASH",
        "kind": "predicate",
        "predicate": {
          "op": "gte",
          "args": [
            {
              "ref": "finance.minimumHeadroom"
            },
            {
              "literal": 0
            }
          ]
        }
      },
      {
        "id": "delivery-capacity",
        "requirement": "CAPACITY",
        "kind": "predicate",
        "predicate": {
          "op": "lte",
          "args": [
            {
              "ref": "derived.capacityHours"
            },
            {
              "ref": "derived.availableHours"
            }
          ]
        }
      },
      {
        "id": "delivery-period",
        "requirement": "CAPACITY",
        "kind": "predicate",
        "predicate": {
          "op": "or",
          "args": [
            {
              "op": "eq",
              "args": [
                {
                  "ref": "derived.customers"
                },
                {
                  "literal": 0
                }
              ]
            },
            {
              "op": "and",
              "args": [
                {
                  "op": "gte",
                  "args": [
                    {
                      "ref": "derived.deliveryStartDay"
                    },
                    {
                      "op": "lookup",
                      "table": "capacityPeriods",
                      "where": {
                        "id": {
                          "op": "lookup",
                          "table": "outcomes",
                          "where": {
                            "scenario": {
                              "ref": "scenario.id"
                            },
                            "arrangement": {
                              "ref": "choice.arrangement"
                            }
                          },
                          "column": "capacityPeriod"
                        }
                      },
                      "column": "from"
                    }
                  ]
                },
                {
                  "op": "lte",
                  "args": [
                    {
                      "ref": "derived.deliveryFinishDay"
                    },
                    {
                      "op": "lookup",
                      "table": "capacityPeriods",
                      "where": {
                        "id": {
                          "op": "lookup",
                          "table": "outcomes",
                          "where": {
                            "scenario": {
                              "ref": "scenario.id"
                            },
                            "arrangement": {
                              "ref": "choice.arrangement"
                            }
                          },
                          "column": "capacityPeriod"
                        }
                      },
                      "column": "through"
                    }
                  ]
                },
                {
                  "op": "gt",
                  "args": [
                    {
                      "ref": "derived.deliveryFinishDay"
                    },
                    {
                      "ref": "derived.deliveryStartDay"
                    }
                  ]
                }
              ]
            }
          ]
        }
      },
      {
        "id": "decision-cutoff",
        "requirement": "TIME",
        "kind": "predicate",
        "predicate": {
          "op": "or",
          "args": [
            {
              "op": "eq",
              "args": [
                {
                  "ref": "choice.arrangement"
                },
                {
                  "literal": "baseline"
                }
              ]
            },
            {
              "op": "lte",
              "args": [
                {
                  "ref": "parameter.currentDay"
                },
                {
                  "ref": "parameter.decisionDeadlineDay"
                }
              ]
            }
          ]
        }
      },
      {
        "id": "planning-horizon",
        "requirement": "TIME",
        "kind": "predicate",
        "predicate": {
          "op": "and",
          "args": [
            {
              "op": "or",
              "args": [
                {
                  "op": "eq",
                  "args": [
                    {
                      "ref": "derived.campaignExpense"
                    },
                    {
                      "literal": 0
                    }
                  ]
                },
                {
                  "op": "lte",
                  "args": [
                    {
                      "ref": "derived.campaignExpenseDay"
                    },
                    {
                      "ref": "parameter.horizonDay"
                    }
                  ]
                }
              ]
            },
            {
              "op": "or",
              "args": [
                {
                  "op": "eq",
                  "args": [
                    {
                      "ref": "derived.deliveryExpense"
                    },
                    {
                      "literal": 0
                    }
                  ]
                },
                {
                  "op": "lte",
                  "args": [
                    {
                      "ref": "derived.deliveryExpenseDay"
                    },
                    {
                      "ref": "parameter.horizonDay"
                    }
                  ]
                }
              ]
            },
            {
              "op": "or",
              "args": [
                {
                  "op": "eq",
                  "args": [
                    {
                      "ref": "derived.customerReceipts"
                    },
                    {
                      "literal": 0
                    }
                  ]
                },
                {
                  "op": "lte",
                  "args": [
                    {
                      "ref": "derived.customerReceiptDay"
                    },
                    {
                      "ref": "parameter.horizonDay"
                    }
                  ]
                }
              ]
            },
            {
              "op": "or",
              "args": [
                {
                  "op": "eq",
                  "args": [
                    {
                      "ref": "derived.customers"
                    },
                    {
                      "literal": 0
                    }
                  ]
                },
                {
                  "op": "lte",
                  "args": [
                    {
                      "ref": "derived.deliveryFinishDay"
                    },
                    {
                      "ref": "parameter.horizonDay"
                    }
                  ]
                }
              ]
            }
          ]
        }
      },
      {
        "id": "future-campaignExpenseDay",
        "requirement": "TIME",
        "kind": "predicate",
        "predicate": {
          "op": "or",
          "args": [
            {
              "op": "eq",
              "args": [
                {
                  "ref": "derived.campaignExpense"
                },
                {
                  "literal": 0
                }
              ]
            },
            {
              "op": "gte",
              "args": [
                {
                  "ref": "derived.campaignExpenseDay"
                },
                {
                  "ref": "parameter.currentDay"
                }
              ]
            }
          ]
        }
      },
      {
        "id": "future-deliveryExpenseDay",
        "requirement": "TIME",
        "kind": "predicate",
        "predicate": {
          "op": "or",
          "args": [
            {
              "op": "eq",
              "args": [
                {
                  "ref": "derived.deliveryExpense"
                },
                {
                  "literal": 0
                }
              ]
            },
            {
              "op": "gte",
              "args": [
                {
                  "ref": "derived.deliveryExpenseDay"
                },
                {
                  "ref": "parameter.currentDay"
                }
              ]
            }
          ]
        }
      },
      {
        "id": "future-customerReceiptDay",
        "requirement": "TIME",
        "kind": "predicate",
        "predicate": {
          "op": "or",
          "args": [
            {
              "op": "eq",
              "args": [
                {
                  "ref": "derived.customerReceipts"
                },
                {
                  "literal": 0
                }
              ]
